import os
from typing import Callable, Optional, Dict, Any

from google.cloud import speech_v1p1beta1 as speech


class StreamingSpeechToText:
    def __init__(
        self,
        on_partial: Optional[Callable[[str, Dict[str, Any]], None]] = None,
        on_final: Optional[Callable[[str, Dict[str, Any]], None]] = None,
        language_code: str = "en-US",
        sample_rate_hz: int = 16000,
        encoding: speech.RecognitionConfig.AudioEncoding = speech.RecognitionConfig.AudioEncoding.LINEAR16,
        model: str = "latest_long",
    ):
        self.client = speech.SpeechClient()
        self.on_partial = on_partial
        self.on_final = on_final
        self.streaming_config = speech.StreamingRecognitionConfig(
            config=speech.RecognitionConfig(
                encoding=encoding,
                sample_rate_hertz=sample_rate_hz,
                language_code=language_code,
                model=model,
            ),
            interim_results=True,
            single_utterance=False,
        )

    def transcribe_stream(self, audio_chunks):
        requests = (
            speech.StreamingRecognizeRequest(audio_content=chunk)
            for chunk in audio_chunks
            if chunk
        )

        responses = self.client.streaming_recognize(
            config=self.streaming_config,
            requests=requests,
        )

        for response in responses:
            if not response.results:
                continue

            for result in response.results:
                if not result.alternatives:
                    continue

                transcript = result.alternatives[0].transcript.strip()
                if not transcript:
                    continue

                payload = {
                    "is_final": result.is_final,
                    "stability": getattr(result, "stability", None),
                    "confidence": getattr(result.alternatives[0], "confidence", None),
                }

                if result.is_final:
                    if self.on_final:
                        self.on_final(transcript, payload)
                else:
                    if self.on_partial:
                        self.on_partial(transcript, payload)


def stream_from_file_like(file_like, chunk_size: int = 4096):
    while True:
        data = file_like.read(chunk_size)
        if not data:
            break
        yield data


def create_streaming_recognizer(
    on_partial: Optional[Callable[[str, Dict[str, Any]], None]] = None,
    on_final: Optional[Callable[[str, Dict[str, Any]], None]] = None,
    language_code: str = "en-US",
    sample_rate_hz: int = 16000,
) -> StreamingSpeechToText:
    return StreamingSpeechToText(
        on_partial=on_partial,
        on_final=on_final,
        language_code=language_code,
        sample_rate_hz=sample_rate_hz,
    )


if __name__ == "__main__":
    recognizer = create_streaming_recognizer(
        on_partial=lambda text, meta: print(f"PARTIAL: {text} | {meta}"),
        on_final=lambda text, meta: print(f"FINAL: {text} | {meta}"),
    )

    audio_path = os.environ.get("AUDIO_PATH")
    if audio_path:
        with open(audio_path, "rb") as f:
            recognizer.transcribe_stream(stream_from_file_like(f))
